-- ----------------------------
-- Table structure for biz_course_order
-- ----------------------------
DROP TABLE IF EXISTS `biz_course_order`;
CREATE TABLE `biz_course_order`  (
  `order_id` bigint NOT NULL AUTO_INCREMENT COMMENT '订单ID',
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '订单流水号',
  `buyer_id` bigint NOT NULL COMMENT '购买者(学生)ID',
  `course_id` bigint NOT NULL COMMENT '购买的课程ID',
  `amount` decimal(10, 2) NOT NULL COMMENT '支付金额',
  `pay_status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '0' COMMENT '支付状态（0待支付 1已支付 2已取消）',
  `create_time` datetime NULL DEFAULT NULL COMMENT '下单时间',
  `pay_time` datetime NULL DEFAULT NULL COMMENT '支付时间',
  PRIMARY KEY (`order_id`) USING BTREE,
  UNIQUE INDEX `idx_order_no`(`order_no` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 10 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '课程交易订单表' ROW_FORMAT = Dynamic;

