-- ----------------------------
-- Table structure for biz_creator_settlement
-- ----------------------------
DROP TABLE IF EXISTS `biz_creator_settlement`;
CREATE TABLE `biz_creator_settlement`  (
  `settlement_id` bigint NOT NULL AUTO_INCREMENT COMMENT '结算流水ID',
  `creator_id` bigint NOT NULL COMMENT '创作者ID',
  `order_id` bigint NOT NULL COMMENT '来源订单ID',
  `profit_amount` decimal(10, 2) NOT NULL COMMENT '分润金额',
  `settlement_status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '0' COMMENT '结算状态（0待结算 1已结算）',
  `create_time` datetime NULL DEFAULT NULL COMMENT '记录生成时间',
  `settlement_time` datetime NULL DEFAULT NULL COMMENT '实际结算时间',
  PRIMARY KEY (`settlement_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 7 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '创作者收益结算流水表' ROW_FORMAT = Dynamic;

