-- ----------------------------
-- Table structure for biz_experiment_record
-- ----------------------------
DROP TABLE IF EXISTS `biz_experiment_record`;
CREATE TABLE `biz_experiment_record`  (
  `record_id` bigint NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `student_id` bigint NOT NULL COMMENT '学生ID(sys_user)',
  `course_id` bigint NOT NULL COMMENT '课程(实验)ID',
  `experiment_data` json NULL COMMENT '学生填写的JSON实验数据',
  `ai_analysis` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '大模型的预检分析与建议(诊断结果)',
  `report_url` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '生成的Word实验报告下载地址',
  `score` int NULL DEFAULT NULL COMMENT '实验自动评分(0-100)',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '0' COMMENT '实验状态（0进行中 1已完成）',
  `del_flag` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '0' COMMENT '删除标志',
  `create_time` datetime NULL DEFAULT NULL COMMENT '实验开始时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '报告生成结束时间',
  PRIMARY KEY (`record_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 20 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '学生实验过程记录表' ROW_FORMAT = Dynamic;

