-- ----------------------------
-- Table structure for biz_video_extraction
-- ----------------------------
DROP TABLE IF EXISTS `biz_video_extraction`;
CREATE TABLE `biz_video_extraction`  (
  `extraction_id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `course_id` bigint NOT NULL COMMENT '课程ID',
  `asr_text` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT 'ASR语音转写全文',
  `ai_summary` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '大模型提炼的课程总结及考点',
  `extraction_status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '0' COMMENT '提取状态（0提取中 1成功 2失败）',
  `create_time` datetime NULL DEFAULT NULL COMMENT '处理时间',
  PRIMARY KEY (`extraction_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 17 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '视频AI知识提取结果表' ROW_FORMAT = Dynamic;

