-- Records of biz_video_extraction
-- ----------------------------
INSERT INTO `biz_video_extraction` VALUES (12, 6, '嗯，实验名称，练习使用显微镜实验目的练习使用光学显微镜学习规范的操作方法，实验用品，写有字母e的，再不片纱布，擦镜纸，毛巾上放废弃物的大烧杯，显微镜，取镜和安放，打开装有显微镜的箱子，用一只手握住镜臂，另一只手托住镜座，轻轻取出显微镜把显微镜放在实验台上。 铝片身体的左侧使显微镜具实验台的边缘约七厘米，大约一掌宽安分好目镜和物镜对光转动转换器使低倍物镜对准通光孔物镜。 前端与债务台要保持大约两厘米的距离，把一个较大的光圈正对通光孔一只眼注视目镜内，另一只眼睁开，转动反光镜，使光线通过通光孔反射到镜筒内，通过目镜可以看到明亮的圆形视野，把所要观察的所有字母e的载玻片标本放在载在在舞台上，用压片夹压住，标本要正对通光孔的中心观察，转动粗准焦螺旋使镜筒缓缓下降，直到物镜接近玻片。 标本为止，此时眼睛一定要看着物镜的下端，左眼向目镜内看，同时逆时针方向转动粗准焦螺旋使镜筒缓缓上升，直到看到物像为止，在略微转动细准焦螺旋使看到的物像更清晰，并将所观察的物像移至视野中央整理器材，观察实验完毕后，将镜头向上抬高，取出拨片标本，用纱布把显微镜的外表擦拭干。 安静如需擦拭目镜和物镜，请用擦镜纸擦镜头时，要顺着一个方向擦拭，不要来回擦拭，然后转动转换器取下固定，并将镜筒缓缓下降到最低处，然后趋向目镜放回镜盒内。 最后把显微镜放进镜箱里，送回原处，用毛巾将实验桌面擦净，实验用品整齐的放在实验桌前方实验结束。 ', '### **实验主旨**\n本实验旨在通过规范操作光学显微镜观察“字母e”玻片标本，使学生掌握显微镜的基本使用方法、操作流程及维护要点，培养严谨的实验习惯和科学观察能力。\n\n---\n\n### **核心理论与操作要点**\n1. **显微镜结构认知**  \n   - 关键部件包括**目镜、物镜、转换器、载物台、压片夹、反光镜、粗/细准焦螺旋**等。\n   - 低倍物镜（如10×）为初始观察首选，需对准通光孔并保持与载物台约2厘米距离。\n\n2. **规范操作流程**  \n   - **取镜与安放**：一手握镜臂，一手托镜座；放置时镜臂朝左，距桌沿约7厘米（一掌宽）。\n   - **对光**：转动转换器使低倍物镜对准通光孔→调节光圈→转动反光镜（光源为自然光或灯光）直至目镜中看到**明亮的圆形视野**。\n   - **观察**：  \n     a. 玻片标本（字母e）置于载物台，用压片夹固定，**正对通光孔中心**。  \n     b. **镜筒下降时**眼睛必须注视物镜下端，防止压碎玻片。  \n     c. 左眼观察目镜，逆时针转动粗准焦螺旋缓慢上升镜筒，直至看到物像，再用细准焦螺旋微调清晰度。  \n     d. 移动玻片将目标物像调至视野中央。\n\n3. **成像原理**  \n   - 显微镜成**倒立放大虚像**（如字母“e”在视野中显示为上下左右颠倒的像）。\n   - 物像移动方向与玻片移动方向相反（如玻片向右移，物像向左移）。\n\n---\n\n### **易出错环节与注意事项**\n1. **操作顺序错误**  \n   - 未先使用**低倍物镜**而直接换高倍镜，可能导致找不到视野或损坏玻片。\n   - 对光前未确保物镜对准通光孔，造成视野昏暗。\n\n2. **调焦操作风险**  \n   - **镜筒下降时未注视物镜**：可能压碎玻片或损坏物镜镜头。\n   - 调节粗准焦螺旋过快：易错过清晰像面或碰撞玻片。\n\n3. **清洁与维护误区**  \n   - 用纱布擦拭镜头：应使用专用**擦镜纸**，沿单一方向轻擦，避免划伤镜片。\n   - 未将镜筒降至最低或物镜未呈“八”字形存放：可能影响显微镜机械结构稳定性。\n\n4. **观察习惯问题**  \n   - 观察时紧闭右眼：应保持双眼睁开，减少疲劳并便于记录。\n   - 未将目标移至视野中央即转换高倍镜：可能导致目标偏离视野。\n\n5. **整理环节疏漏**  \n   - 实验后未升高镜筒直接取玻片，或未用压片夹固定玻片导致滑落。\n   - 未清洁载物台及归位器材，影响后续使用。\n\n---\n\n### **关键提示**\n- **安全第一**：调焦时“眼观物镜”，下降镜筒需缓慢。\n- **规范维护**：镜头清洁仅用擦镜纸，存放前恢复显微镜初始状态（镜筒最低、物镜非通光孔位）。\n- **成像理解**：通过观察字母“e”的倒像，直观理解显微镜光学特性。', '1', '2026-03-07 12:53:03');
INSERT INTO `biz_video_extraction` VALUES (13, 7, '嗯，用刻度尺测量长度器材有毫米刻度尺，三角版物理课本硬币30厘米长的细导线，铅笔实验步骤，检查器材，观察并记录刻度尺的量程和分度值零刻度线是否磨损，用刻度尺测课本的长和宽，将刻度尺的刻度线紧贴柄平行刻。 我的旁边，将邻刻度线对准一专，然后观察另一端所对的刻度线，读数时视线与尺面垂直要求估读到分度值的下一位，将刻度尺的刻度线紧贴柄平行课本的短片，将邻刻度线对准一专，然后观察另一端所对的刻度线，读数时视线与尺面垂直要求估读到分度值的下一位，用刻度尺和三角板测硬币的直径。 用两块三角板的一直角边将硬币卡紧另一直角边与刻度尺紧贴移动三角板和硬币刻度尺某一整数刻度线与被测直径的一端对齐，然后观察另一端所对的刻度线，读数时视线与尺面垂直要求估读到分度值的下一位测试导线直径，将细导线在铅笔上紧密缠绕着。 十圈用刻度尺测出线圈的长度计算，并记录细导线的直径，整理器材本实验完毕。 你会不会一样一样一样？ ', '根据您提供的实验语音转写文字，我为您提炼出该实验课程的核心要点。\n\n### **一、实验主旨**\n本实验旨在教授并训练学生**正确使用毫米刻度尺进行长度测量**的基本技能。通过测量不同物体（规则书本、小尺寸硬币、细软导线），掌握针对不同测量对象的多种测量方法，并深入理解“估读”这一核心概念。\n\n### **二、核心理论与方法**\n1.  **刻度尺使用规范**：\n    *   **放正**：刻度线需紧贴被测物体，并与被测边**平行**。\n    *   **对准**：将**零刻度线或某一整数刻度线**与被测物体的一端对齐。\n    *   **垂直读数**：读数时，视线必须与尺面**垂直**，以减小视差误差。\n    *   **记录完整**：测量结果必须**注明单位**。\n\n2.  **特殊测量方法**：\n    *   **组合法（测硬币直径）**：利用两个三角板的直角边将硬币卡紧，形成一个平行于刻度尺的“卡槽”，将不易直接放置的**圆形物体直径**的测量转化为对卡槽间距离的测量。\n    *   **累积法（测导线直径）**：将细导线在铅笔上**紧密缠绕N圈（如10圈）**，测量线圈的总长度L，则单根导线的直径 d = L / N。此法用于测量**微小长度**，可放大测量值，减小相对误差。\n\n3.  **读数核心原则**：\n    *   **估读**：必须**估读到分度值（最小刻度）的下一位**。这是实验数据科学性和精确性的关键要求。\n\n### **三、容易出错的地方**\n1.  **操作错误**：\n    *   刻度尺**未紧贴**或**未与待测边平行**放置。\n    *   测量圆形直径时，三角板卡放不紧或未与刻度尺紧贴，导致所测并非**真正的直径**。\n    *   缠绕导线时**各圈之间留有缝隙**或**重叠**，导致累积法计算出的直径不准确。\n\n2.  **读数与记录错误**：\n    *   **视线倾斜**，未与尺面垂直，造成**视差**。\n    *   忘记或错误进行**估读**（例如，毫米刻度尺只读到毫米位）。\n    *   记录结果时**漏写单位**或单位错误。\n    *   使用磨损的零刻度线时，未用整数刻度线重新对齐，也未在计算时**减去起始刻度值**。\n\n3.  **方法与计算错误**：\n    *   在累积法中，**忘记用总长度除以圈数**，误将线圈总长当作单根直径。\n    *   计算时，**单位未统一换算**（如将厘米值直接用于毫米计算）。\n\n**总结**：本实验是物理测量的基础，重点在于**规范的操作流程、灵活的测量策略以及对“估读”规则的严格执行**。避免上述常见错误，是获得准确、有效测量数据的关键。', '1', '2026-03-07 15:07:48');
INSERT INTO `biz_video_extraction` VALUES (14, 10, '实验名称测量平均速度器材有带刻度的木板停表，小车金属片木块实验步骤，检查器材，观察木板上刻度尺的量程和分度值观察停表的分度值练习使用停表，将木板柚木块地。 建起组成鞋面，使小车从顶端静止释放，能在鞋面上缓慢下滑到木板的底端，反复调试坡度测量小车从顶端到底端，将要通过的路程并记录。 然后找出小车通过路程的中点位置记录顶端到终点的路程，用廷表测量小车从顶端静止释放，下滑到撞击底端的时间，并记录将金属片安装在终点位置。 用停表测量小车从顶端静止释放，下滑到撞击金属片的时间，并记录整理器材摆放整齐，计算小车两次运动的平均速度。 本实验结束。 ', '### **实验主旨**\n本实验旨在通过测量小车在斜面上不同路段（全程与半程）的运动时间，学习并掌握**平均速度**的测量与计算方法，理解平均速度是描述物体在一段路程内运动快慢的物理量。\n\n### **核心理论**\n1.  **平均速度公式**：平均速度（v）等于物体通过的路程（s）除以所用的时间（t），即 **v = s / t**。\n2.  **实验原理**：通过测量小车从斜面顶端**静止释放**后，下滑通过**固定路程**所用的时间，利用上述公式即可计算出该段路程内的平均速度。\n3.  **对比分析**：通过比较小车在斜面全程和前半程的平均速度，可以直观地理解物体做**加速运动**时，在不同路段上的平均速度是不同的（后半程平均速度会大于前半程）。\n\n### **容易出错的地方**\n1.  **斜面坡度调试不当**：斜面坡度太陡，小车下滑过快，不易准确计时；坡度太缓，小车可能无法自行滑下或中途停止。需反复调试，使小车能**从静止开始缓慢、匀速地**滑下。\n2.  **计时操作不准确**：\n    *   **起止时刻判断错误**：计时必须与小车**从顶端静止释放**的瞬间同时开始，并在小车**撞击金属片（或底端）** 的瞬间同时结束。\n    *   **停表操作不熟练**：需提前练习停表的启动、停止和复位，避免因操作延误导致时间测量出现较大误差。\n3.  **路程测量与标记错误**：\n    *   路程应从**小车释放点（顶端）** 开始测量到**金属片所在位置**，需准确读取刻度尺示数。\n    *   金属片应**垂直固定**在木板中点，确保小车每次撞击位置一致。\n4.  **实验次数不足**：为减小误差，同一段路程的时间测量应进行**多次**，然后取平均值进行计算。\n5.  **公式计算错误**：计算平均速度时，需注意路程（s）和时间（t）的**单位统一**（通常路程用米“m”，时间用秒“s”，速度用米每秒“m/s”）。', '1', '2026-03-08 16:57:52');
INSERT INTO `biz_video_extraction` VALUES (15, 4, '嗯嗯。 ', '好的，我已准备好。请您提供实验视频的语音转写文字，我将为您提炼出：\n\n1.  **实验主旨**：本次实验的核心目的与要解决的关键问题。\n2.  **核心理论**：支撑该实验操作的关键科学原理、公式或定律。\n3.  **易错点与注意事项**：在操作步骤、数据记录、现象分析等环节中容易出错的地方及安全要点。\n\n请将文字内容发送给我，我即刻为您分析总结。', '1', '2026-03-17 14:28:56');
INSERT INTO `biz_video_extraction` VALUES (16, 13, '嗯，探究凸透镜成实像的特点实验器材，光具座，凸透镜，光凭f光源或蜡烛探究过程，提出问题，凸透镜成实像时物距分别满足什么条件猜想与假设凸透镜成缩小实像时物距可能大于二倍焦距凸透镜成放大实像时物距可能大于一倍焦距小于二倍焦距设计，并进行实验检查器材观察凸透镜的焦距大小并济。 一路把凸透镜固定在光具座上，50厘米刻度线处f光源光屏安装在凸透镜的两侧，闭合电源开关将三者靠拢，通过调节使光源中心，透镜光心，光屏中心在同一高度移动光源到大于凸透镜的2倍焦距猛促在左右一。 用光屏，直到光屏上的成像最清晰为止，记录此时的物距，优衣及成像特点，移动光源到一倍焦距和二倍焦距之间某处在左右移动光屏直到光屏上的影像最清晰为止。 记录此时的物距u2及长相特点，断开官员开关，取下光源，凸透镜，光屏放回原处分析数据，得出结论，物体到凸透镜的距离大于二倍焦距时。 成倒立缩小的实像物体到凸透镜的距离大于一倍焦距小于二倍焦距时很倒立，放大的实像半实验结束。 ', '### **实验主旨**\n探究凸透镜成实像时，物距与成像特点（大小、倒正）之间的规律。\n\n---\n\n### **核心理论**\n1. **实像的形成条件**：物体必须位于凸透镜的**一倍焦距以外**（u > f），才能在光屏上接收到倒立的实像。\n2. **物距与像的缩放关系**：\n   *   **缩小实像**：当物距**大于二倍焦距**（u > 2f）时，成倒立、缩小的实像。\n   *   **放大实像**：当物距**大于一倍焦距且小于二倍焦距**（f < u < 2f）时，成倒立、放大的实像。\n3. **实验关键操作**：必须调节**光源中心、透镜光心、光屏中心**在同一高度（共轴），以确保像能完整呈现在光屏中央。\n\n---\n\n### **容易出错的地方**\n1. **器材调节**：\n   *   未将光源、透镜、光屏三者的中心调至同一高度，导致像无法在光屏上完整呈现或根本找不到像。\n   *   未事先了解或标注凸透镜的焦距（f），导致无法准确设定物距范围。\n2. **物距控制与判断**：\n   *   误将物体放在**一倍焦距以内**（u < f），此时成虚像，光屏上无法接收到，导致实验失败。\n   *   在“一倍焦距到二倍焦距之间”移动光源时，位置控制不精确，容易过于靠近焦点或二倍焦距点，影响对“放大”特性的观察。\n3. **成像清晰度判断**：\n   *   左右移动光屏寻找像时，未耐心缓慢调节至**最清晰**状态就记录数据，导致像距测量不准确，影响结论。\n4. **实验习惯**：\n   *   实验结束后，忘记断开电源开关或未将器材整理归位。', '1', '2026-03-17 16:51:20');

-- ----------------------------
-- Table structure for gen_table
-- ----------------------------
DROP TABLE IF EXISTS `gen_table`;
CREATE TABLE `gen_table`  (
  `table_id` bigint NOT NULL AUTO_INCREMENT COMMENT '编号',
  `table_name` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT '' COMMENT '表名称',
  `table_comment` varchar(500) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT '' COMMENT '表描述',
  `sub_table_name` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '关联子表的表名',
  `sub_table_fk_name` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '子表关联的外键名',
  `class_name` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT '' COMMENT '实体类名称',
  `tpl_category` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT 'crud' COMMENT '使用的模板（crud单表操作 tree树表操作）',
  `tpl_web_type` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT '' COMMENT '前端模板类型（element-ui模版 element-plus模版）',
  `package_name` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '生成包路径',
  `module_name` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '生成模块名',
  `business_name` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '生成业务名',
  `function_name` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '生成功能名',
